pub fn bmi(kg:f64,cm:f64)->Option<f64>{ if !kg.is_finite()||!cm.is_finite()||kg<=0.||cm<=0.{None}else{Some(kg/(cm/100.).powi(2))} }
pub fn bmr(kg:f64,cm:f64,age:f64,male:bool)->Option<f64>{ if bmi(kg,cm).is_none()||!(18.0..=120.0).contains(&age){None}else{Some(10.*kg+6.25*cm-5.*age+if male{5.}else{-161.})} }
pub fn calculate(s:&str)->Result<f64,String>{ let s=s.trim().trim_start_matches('='); let mut p=Parser{s:s.as_bytes(),i:0}; let n=p.expr()?;p.ws();if p.i!=p.s.len()||!n.is_finite(){Err("Invalid expression".into())}else{Ok(n)} }
struct Parser<'a>{s:&'a [u8],i:usize}
impl Parser<'_>{ fn ws(&mut self){while self.s.get(self.i).is_some_and(u8::is_ascii_whitespace){self.i+=1}} fn eat(&mut self,c:u8)->bool{self.ws();if self.s.get(self.i)==Some(&c){self.i+=1;true}else{false}} fn expr(&mut self)->Result<f64,String>{let mut n=self.term()?;loop{if self.eat(b'+'){n+=self.term()?}else if self.eat(b'-'){n-=self.term()?}else{break}}Ok(n)} fn term(&mut self)->Result<f64,String>{let mut n=self.atom()?;loop{if self.eat(b'*'){n*=self.atom()?}else if self.eat(b'/'){let d=self.atom()?;if d==0.{return Err("Division by zero".into())}n/=d}else{break}}Ok(n)} fn atom(&mut self)->Result<f64,String>{self.ws();if self.eat(b'-'){return Ok(-self.atom()?)}if self.eat(b'+'){return self.atom()}if self.eat(b'('){let n=self.expr()?;if !self.eat(b')'){return Err("Missing )".into())}return Ok(n)}let start=self.i;while self.s.get(self.i).is_some_and(|c|c.is_ascii_digit()||*c==b'.'){self.i+=1}if start==self.i{return Err("Enter a number".into())}std::str::from_utf8(&self.s[start..self.i]).ok().and_then(|s|s.parse().ok()).ok_or_else(||"Invalid number".into())}}
#[cfg(test)]mod tests{use super::*;#[test]fn arithmetic(){assert_eq!(calculate("(12+8)*2").unwrap(),40.);assert!(calculate("1/0").is_err());assert!(calculate("2garbage").is_err())}#[test]fn body(){assert!((bmi(90.,173.).unwrap()-30.0718).abs()<0.01);assert_eq!(bmr(70.,170.,30.,true),Some(1617.5))}}
